// Original progressive drawing plates. Coordinates are teaching diagrams, not physical centimetres.
export function tangentPoints(O,P,r){let dx=P[0]-O[0],dy=P[1]-O[1],d2=dx*dx+dy*dy;if(d2<=r*r)return[];let a=r*r/d2,b=r*Math.sqrt(d2-r*r)/d2;return[[O[0]+a*dx-b*dy,O[1]+a*dy+b*dx],[O[0]+a*dx+b*dy,O[1]+a*dy-b*dx]]}
export function drawArt10(canvas,ch,step=9,level='Good'){
 const g=canvas.getContext('2d'),s=Math.max(0,Math.min(9,step)),n=ch.artTopic,C=ch.palette.map(p=>p.color);g.setTransform(canvas.width/600,0,0,canvas.height/400,0,0);g.clearRect(0,0,600,400);g.fillStyle=C[0];g.fillRect(0,0,600,400);g.strokeStyle='#304b43';g.lineWidth=level==='Beginner'?3:1.5;g.lineCap='round';g.lineJoin='round';
 const line=(x,y,X,Y,col='#304b43',dash=false)=>{g.save();g.strokeStyle=col;if(dash)g.setLineDash([5,4]);g.beginPath();g.moveTo(x,y);g.lineTo(X,Y);g.stroke();g.restore()};
 const path=(d,fill)=>{let p=new Path2D(d);if(fill){g.fillStyle=fill;g.fill(p)}g.stroke(p)};
 const circle=(x,y,r,fill)=>{g.beginPath();g.arc(x,y,r,0,Math.PI*2);if(fill){g.fillStyle=fill;g.fill()}g.stroke()};
 const ellipse=(x,y,a,b,fill)=>{g.beginPath();g.ellipse(x,y,a,b,0,0,Math.PI*2);if(fill){g.fillStyle=fill;g.fill()}g.stroke()};
 const txt=(v,x,y,size=14)=>{if(ch.hideLabels)return;g.fillStyle='#243e35';g.font=`${size}px "Noto Sans Devanagari",sans-serif`;g.fillText(v,x,y)};
 const shade=(x,X)=>{if(level==='Beginner')return C[2];let z=g.createLinearGradient(x,0,X,0);z.addColorStop(0,C[1]);z.addColorStop(.25,level==='Intermediate'?C[1]:C[0]);z.addColorStop(.65,C[2]);z.addColorStop(1,C[3]);return z};
 if(n===1){txt('Line · Shape · Form | रेखा · आकार · रूप',45,40,18);line(50,95,210,95);if(s>=1){line(50,130,210,130);path('M50 170Q130 110 210 170')}if(s>=2){circle(315,115,48);path('M420 68H515V163H420Z')}if(s>=3){let z=g.createRadialGradient(290,240,1,320,265,62);z.addColorStop(0,'#fffdf5');z.addColorStop(1,'#3d594c');circle(320,265,60,s>=4?z:null)}if(s>=5)for(let i=0;i<5;i++){g.fillStyle=['#f3ecda','#c5c6b8','#8f9d8e','#597768','#263f36'][i];g.fillRect(45+i*34,235,34,60)}if(s>=6)for(let i=0;i<7;i++)line(425+i*12,220,450+i*12,310);if(s>=7)for(let i=0;i<3;i++)circle(85+i*55,350,20,C[i+1]);if(s>=8)txt('Tone / तान',65,320);if(s>=9)txt('Observe → simplify → refine | देखें → सरल करें → सुधारें',40,390,13);
 }else if(n===2||n===3){let horizon=190;line(35,horizon,565,horizon);if(s>=1){path('M35 190L145 90L238 190L345 68L475 190L565 120V300H35Z',s>=4?C[2]:null)}if(s>=2)circle(n===2?460:110,110,30,s>=4?C[1]:null);if(s>=3)path('M270 190Q220 250 330 270Q470 310 360 365L195 365Q320 310 230 280Q170 245 270 190Z',s>=5?C[3]:null);if(s>=4){g.save();g.globalCompositeOperation='destination-over';g.fillStyle=C[0];g.fillRect(0,0,600,400);g.restore()}if(s>=5){path('M65 255L120 215L180 255Z',C[3]);path('M78 255H165V310H78Z',C[1]);if(n===3){path('M410 245L450 215L495 245Z',C[3]);path('M420 245H485V285H420Z',C[1])}}if(s>=6){path('M108 310V275H131V310',C[4]);line(50,345,200,320);line(430,330,550,355)}if(s>=7){line(525,340,525,230);circle(525,230,36,C[4]);circle(500,245,25,C[4])}if(s>=8){for(let i=0;i<6;i++)line(55+i*22,350,60+i*22,335,C[4]);line(490,345,555,350,C[4])}if(s>=9)txt('Near: larger / पास: बड़ा · Far: lighter / दूर: हल्का',45,385,13);
 }else if(n===4||n===5){const cx=300,cy=205,r=140;if(n===4)circle(cx,cy,r);else path('M160 65H440V345H160Z');if(s>=1){line(145,cy,455,cy,'#8c9b8a',true);line(cx,50,cx,360,'#8c9b8a',true)}if(s>=2)circle(cx,cy,28,s>=6?C[2]:null);let petals=s<3?0:s===3?1:s===4?2:s===5?4:8;for(let i=0;i<petals;i++){g.save();g.translate(cx,cy);g.rotate(i*Math.PI/4);path('M0 -25Q-60 -65 0 -120Q60 -65 0 -25Z',s>=6?C[1+i%3]:null);g.restore()}if(s>=7){if(n===4)circle(cx,cy,r-10);else path('M170 75H430V335H170Z')}if(s>=8)for(let i=0;i<8;i++){let a=i*Math.PI/4;circle(cx+128*Math.cos(a),cy+128*Math.sin(a),4,C[3])}if(s>=9)txt('One complete motif · 3 colours | 1 पूर्ण इकाई · 3 रंग',100,385,14);
 }else if(n===6){let O=[210,210],P=[490,210],r=100,T=tangentPoints(O,P,r);circle(...O,r);txt('O',190,230);if(s>=1){circle(...P,3);txt('P',500,215)}if(s>=2)line(...O,...P);if(s>=3){circle(350,210,3);txt('M',343,235)}if(s>=4){g.save();g.setLineDash([5,5]);circle(350,210,140);g.restore()}if(s>=5)T.forEach((p,i)=>{circle(...p,4,C[2]);txt(i?'U':'T',p[0]-15,p[1]+(i?20:-12))});if(s>=6)T.forEach(p=>line(...O,...p,'#789b84'));if(s>=7)T.forEach(p=>line(...P,...p,C[3]));if(s>=8)T.forEach(p=>{let a=[(O[0]-p[0])/100,(O[1]-p[1])/100],d=Math.hypot(P[0]-p[0],P[1]-p[1]),b=[(P[0]-p[0])/d,(P[1]-p[1])/d];path(`M${p[0]+a[0]*12} ${p[1]+a[1]*12}l${b[0]*12} ${b[1]*12}l${-a[0]*12} ${-a[1]*12}`)});if(s>=9)txt('OT ⟂ PT · OU ⟂ PU · PT = PU',150,380,16);
 }else if(n===7){let x=300,y=205,r=125;circle(x,y,r);if(s>=1)line(x-r,y,x+r,y);if(s>=2)line(x,y-r,x,y+r);if(s>=3)[[x-r,y],[x+r,y],[x,y-r],[x,y+r]].forEach((p,i)=>{circle(...p,3);txt('ACBD'[i],p[0]+7,p[1]-8)});if(s>=4)path('M175 205L300 80L425 205L300 330Z',s>=8?C[1]+'66':null);if(s>=5){line(160,80,440,80,C[3]);line(160,330,440,330,C[3])}if(s>=6){line(175,65,175,345,C[3]);line(425,65,425,345,C[3])}if(s>=7)txt('r',310,148);if(s>=8)txt('Inside side = √2r · Outside side = 2r',85,368,15);if(s>=9)txt('अंतर्गत भुजा = √2r · परिगत भुजा = 2r',125,393,14);
 }else if(n===8){path('M100 320L500 320L240 80Z',s>=8?C[1]+'66':null);if(s>=1){line(100,320,500,320,C[3]);txt('b = 8 cm',270,345)}if(s>=2){line(240,80,240,320,'#647968',true);txt('h = 6 cm',245,150)}if(s>=3){circle(240,200,4,C[2]);txt('M',245,198)}if(s>=4)line(80,200,520,200,'#647968',true);if(s>=5)line(100,320,500,320,C[3]);if(s>=6){line(100,320,100,200,C[3]);line(500,320,500,200,C[3])}if(s>=7)line(100,200,500,200,C[3]);if(s>=8)txt('½ × 8 × 6 = 8 × 3 = 24 cm²',155,375,17);if(s>=9)txt('Same base; half height | समान आधार; आधी ऊँचाई',135,30,14);
 }else if(n===9){let x=100,y=280,w=100;line(x,y,500,y);if(s>=1)for(let i=0;i<=4;i++){line(x+i*w,y,x+i*w,y-15);txt(String(i===0?'':i-1),x+i*w-5,y+25)}if(s>=2)for(let i=0;i<=10;i++)line(x+i*10,y,x+i*10,y-10);if(s>=3)txt('Metres / मीटर',265,340,16);if(s>=4){path('M100 280V80H500V280');for(let i=1;i<4;i++)line(100+i*100,80,100+i*100,280,'#9aaa98')}if(s>=5)for(let i=1;i<10;i++)line(100,280-i*20,500,280-i*20,'#b7c5b7');if(s>=6)for(let i=0;i<10;i++)line(110+i*10,280,100+i*10,80,C[3]);if(s>=7){line(166,200,400,200,C[2]);circle(166,200,4,C[2]);circle(400,200,4,C[2])}if(s>=8)txt('2 m + 0.3 m + 0.04 m = 2.34 m',115,35,17);if(s>=9)txt('RF = 1:100 · screen is schematic / स्क्रीन सांकेतिक है',85,385,14);
 }else{ // Memory studies: vessel, produce, or combined arrangement.
 let vessel=n!==11,fruit=n!==10;if(s===0){g.save();g.setLineDash([5,4]);g.strokeRect(90,65,425,280);g.restore()}if(vessel){let x=n===12?130:220;path(`M${x} 115Q${x+45} 105 ${x+90} 115L${x+105} 295Q${x+45} 330 ${x-15} 295Z`,s>=4?shade(x-15,x+105):null);if(s>=1)ellipse(x+45,115,45,10,s>=5?C[3]:null);if(s>=2){line(x+45,75,x+45,335,'#9aa590',true);ellipse(x+45,295,60,14)}if(s>=3)path(`M${x+98} 155C${x+175} 130 ${x+175} 265 ${x+104} 265`)}if(fruit){let x=n===12?365:250;path(`M${x} 225C${x-75} 185 ${x-100} 270 ${x-58} 315Q${x-20} 345 ${x} 323Q${x+50} 348 ${x+73} 297C${x+100} 230 ${x+45} 202 ${x} 225Z`,s>=4?shade(x-80,x+85):null);if(s>=1)path(`M${x} 225Q${x-10} 200 ${x+4} 185`);if(s>=2)path(`M${x} 205Q${x+30} 170 ${x+50} 195Q${x+20} 220 ${x} 205Z`,s>=5?C[4]:null);if(n===11&&s>=3)ellipse(440,290,60,28,s>=4?C[2]:null)}if(s>=6){g.save();g.globalAlpha=.2;ellipse(315,338,210,18,C[4]);g.restore()}if(s>=7){g.strokeStyle='#fff8e2';g.lineWidth=6;line(n===11?200:n===12?145:230,n===11?250:n===12?170:180,n===11?195:n===12?148:232,n===11?275:n===12?225:240,'#fff8e2')}if(s>=8)line(50,350,550,350,'#b1bba8');if(s>=9)txt('Outline → proportion → tone | रूपरेखा → अनुपात → तान',85,385,14);
 }
}
